// PixelFilter.tsx — generated by Pixel Filter.
// Paste into Framer → Assets → Code → New file, then drop it on the canvas
// and set the image in the right panel.
import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

// ─── Engine (inlined) ────────────────────────────────────────────────────────

// __ENGINE__

// ─── Component ───────────────────────────────────────────────────────────────

const DEFAULTS: PixelSettings = __DEFAULTS__

const KEYS = Object.keys(DEFAULTS) as (keyof PixelSettings)[]

interface ResponsiveImageValue {
    src: string
    srcSet?: string
    alt?: string
}

type Props = Partial<PixelSettings> & {
    image?: ResponsiveImageValue
    style?: React.CSSProperties
}

const fill: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    display: "block",
}

/**
 * Animated pixel-block overlay for an image.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 * @framerIntrinsicWidth 800
 * @framerIntrinsicHeight 600
 */
export default function PixelFilter(props: Props) {
    const { image, style } = props
    const settings = {} as PixelSettings
    for (const k of KEYS) (settings as any)[k] = props[k] ?? DEFAULTS[k]

    const wrapRef = React.useRef<HTMLDivElement>(null)
    const imgRef = React.useRef<HTMLImageElement>(null)
    const photoRef = React.useRef<HTMLCanvasElement>(null)
    const blockRef = React.useRef<HTMLCanvasElement>(null)
    const rendererRef = React.useRef<PixelFilterRenderer | null>(null)
    const settingsRef = React.useRef(settings)
    settingsRef.current = settings

    const effective = (s: PixelSettings): PixelSettings => {
        const reduce =
            typeof window !== "undefined" &&
            window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        return reduce ? { ...s, motion: "None" } : s
    }

    React.useEffect(() => {
        const wrap = wrapRef.current
        if (!wrap || !blockRef.current) return
        const r = new PixelFilterRenderer(blockRef.current, photoRef.current, effective(settingsRef.current))
        rendererRef.current = r
        const measure = () => r.setSize(wrap.clientWidth, wrap.clientHeight)
        const ro = new ResizeObserver(measure)
        ro.observe(wrap)
        measure()
        const img = imgRef.current
        if (img && img.complete && img.naturalWidth) r.setImage(img)
        return () => {
            ro.disconnect()
            r.destroy()
            rendererRef.current = null
        }
    }, [])

    const signature = KEYS.map((k) => settings[k]).join("|")
    React.useEffect(() => {
        rendererRef.current?.setSettings(effective(settings))
    }, [signature])

    const src = image?.src
    React.useEffect(() => {
        const r = rendererRef.current
        if (!r) return
        const img = imgRef.current
        r.setImage(img && img.complete && img.naturalWidth ? img : null)
    }, [src])

    const blurred = settings.blur > 0

    return (
        <div
            ref={wrapRef}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                overflow: "hidden",
                isolation: "isolate",
                background: "#0b0b0c",
                ...style,
            }}
        >
            {src ? (
                <img
                    ref={imgRef}
                    crossOrigin="anonymous"
                    src={src}
                    srcSet={image?.srcSet}
                    alt={image?.alt ?? ""}
                    draggable={false}
                    onLoad={(e) => rendererRef.current?.setImage(e.currentTarget)}
                    style={{ ...fill, objectFit: "cover", objectPosition: "center", visibility: blurred ? "hidden" : "visible" }}
                />
            ) : (
                <div
                    style={{
                        ...fill,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: "rgba(255,255,255,0.5)",
                        font: "500 12px/1.4 'IBM Plex Mono', ui-monospace, monospace",
                        letterSpacing: "0.12em",
                        textTransform: "uppercase",
                        textAlign: "center",
                        padding: 16,
                    }}
                >
                    Set an image in the right panel →
                </div>
            )}
            <canvas ref={photoRef} style={{ ...fill, visibility: blurred && src ? "visible" : "hidden" }} />
            <canvas
                ref={blockRef}
                style={{ ...fill, pointerEvents: "none", mixBlendMode: BLEND_CSS[settings.blend] as any }}
            />
        </div>
    )
}

addPropertyControls(PixelFilter, {
    image: { type: ControlType.ResponsiveImage, title: "Image" },
    shape: { type: ControlType.Enum, title: "Shape", options: SHAPES, defaultValue: DEFAULTS.shape },
    pixelSize: { type: ControlType.Number, title: "Pixel Size", min: 4, max: 48, step: 1, defaultValue: DEFAULTS.pixelSize },
    variation: { type: ControlType.Number, title: "Variation", min: 0, max: 1, step: 0.01, defaultValue: DEFAULTS.variation },
    fill: { type: ControlType.Number, title: "Fill", min: 0.2, max: 1.4, step: 0.01, defaultValue: DEFAULTS.fill },
    blur: { type: ControlType.Number, title: "Blur", min: 0, max: 40, step: 1, unit: "px", defaultValue: DEFAULTS.blur },
    coverage: { type: ControlType.Enum, title: "Coverage", options: COVERAGES, defaultValue: DEFAULTS.coverage },
    threshold: { type: ControlType.Number, title: "Threshold", min: 0, max: 1, step: 0.01, defaultValue: DEFAULTS.threshold },
    color: {
        type: ControlType.Enum,
        title: "Color",
        options: COLOR_MODES,
        displaySegmentedControl: true,
        defaultValue: DEFAULTS.color,
    },
    pixelColor: {
        type: ControlType.Color,
        title: "Pixel",
        defaultValue: DEFAULTS.pixelColor,
        hidden: (props: Props) => (props.color ?? DEFAULTS.color) !== "Custom",
    },
    blend: { type: ControlType.Enum, title: "Blend", options: BLENDS, defaultValue: DEFAULTS.blend },
    motion: { type: ControlType.Enum, title: "Motion", options: MOTIONS, defaultValue: DEFAULTS.motion },
    speed: { type: ControlType.Number, title: "Speed", min: 0.1, max: 3, step: 0.05, unit: "x", defaultValue: DEFAULTS.speed },
})
